        "id": "1c022132-227d-4411-bc96-8e13569090d0",
        "name": "Hip Thrust con Barra en Banco",
        "name_es": "Hip Thrust con Barra en Banco",
        "name_en": "Barbell Hip Thrust on Bench",
        "name_pt": "Elevação Pélvica (Hip Thrust) com Barra no Banco",
        "nivel_1_tipo": "muscular",
        "nivel_2_grupo_muscular": "piernas",
        "nivel_3_submusculo_piernas": "gluteos",
        "exercise_type": "muscular",
        "category": "piernas",
