        "id": "c27c05f6-481a-4791-ac2f-6518b89d0d31",
        "name": "Kettlebell Swing Estilo Ruso",
        "name_es": "Kettlebell Swing Estilo Ruso",
        "name_en": "Russian Kettlebell Swing",
        "name_pt": "Kettlebell Swing Estilo Russo",
        "nivel_1_tipo": "cardio",
        "nivel_2_grupo_muscular": "piernas",
        "nivel_3_submusculo_piernas": "gluteos",
        "exercise_type": "cardio",
