        "id": "574b4103-d8f9-46c1-a7e9-24dda37f28bf",
        "name": "Hiperextensiones a 45° para Cadena Posterior",
        "name_es": "Hiperextensiones a 45° para Cadena Posterior",
        "name_en": "45-Degree Back Extension (Posterior Chain)",
        "name_pt": "Hiperextensão Lombar a 45° para Cadeia Posterior",
        "nivel_1_tipo": "muscular",
        "nivel_2_grupo_muscular": "piernas",
