        "id": "76ecb7d1-3d55-488e-be20-e426de097d42",
        "name": "Press de Banca con Barra",
        "name_es": "Press de Banca con Barra",
        "name_en": "Barbell Bench Press",
        "name_pt": "Supino Reto com Barra",
        "nivel_1_tipo": "muscular",
        "nivel_2_grupo_muscular": "pecho",
        "nivel_3_submusculo_piernas": null,
