        "name_en": "45-Degree Incline Dumbbell Biceps Curl",
        "name_pt": "Rosca Bíceps no Banco Inclinado a 45°",
        "nivel_1_tipo": "muscular",
        "nivel_2_grupo_muscular": "biceps",
